namespace mescal {

#ifdef HAVE_MALLOC_USABLE_SIZE

// With malloc_usable_size: use it directly for precise tracking

static void* qjs_malloc(JSMallocState *s, size_t size)
{
    if (size == 0)
        return NULL;

    void *ptr = fastMalloc(size);
    if (ptr) {
        s->malloc_count++;
        s->malloc_size += malloc_usable_size(ptr);
    }
    return ptr;
}

static void qjs_free(JSMallocState *s, void *ptr)
{
    if (!ptr)
        return;

    s->malloc_count--;
    s->malloc_size -= malloc_usable_size(ptr);
    fastFree(ptr);
}

static void* qjs_realloc(JSMallocState *s, void *ptr, size_t size)
{
    if (size == 0) {
        qjs_free(s, ptr);
        return NULL;
    }

    size_t old_size = ptr ? malloc_usable_size(ptr) : 0;
    void *new_ptr = fastRealloc(ptr, size);
    if (new_ptr) {
        s->malloc_size += malloc_usable_size(new_ptr) - old_size;
        if (!ptr)
            s->malloc_count++;
    }
    return new_ptr;
}

static size_t qjs_malloc_usable_size(const void *ptr)
{
    return malloc_usable_size(const_cast<void*>(ptr));
}

#else

// Without malloc_usable_size: prepend a size header to each allocation

#define MALLOC_HEADER_SIZE (sizeof(size_t))

static size_t qjs_malloc_usable_size(const void *ptr)
{
