namespace mescal {

/*
 * Custom memory allocator for QuickJS using WTF::fastMalloc.
 *
 * Contract (from QuickJS source):
 * - malloc_size must track actual usable size + MALLOC_OVERHEAD
 * - malloc_limit must be checked before allocation
 * - malloc_usable_size must return the usable size of a pointer
 * - realloc(ptr, 0) must free and return NULL
 * - malloc(0) must not be called (assert in QuickJS)
 */

#define MALLOC_OVERHEAD 8

static size_t qjs_malloc_usable_size(const void *ptr)
{
#ifdef HAVE_MALLOC_USABLE_SIZE
    return malloc_usable_size(const_cast<void*>(ptr));
#else
    /* Without malloc_usable_size, we cannot know the real size.
     * QuickJS will fall back to tracking requested sizes internally
     * when this returns 0, but memory limit enforcement will be
     * less accurate. This is the same approach as Emscripten. */
    return 0;
#endif
}

static void* qjs_malloc(JSMallocState *s, size_t size)
{
    void *ptr;

    /* QuickJS guarantees size != 0 */
    assert(size != 0);

    if (s->malloc_size + size > s->malloc_limit)
        return NULL;

    ptr = fastMalloc(size);
    if (!ptr)
        return NULL;

    s->malloc_count++;
    s->malloc_size += qjs_malloc_usable_size(ptr) + MALLOC_OVERHEAD;
    return ptr;
}

static void qjs_free(JSMallocState *s, void *ptr)
{
    if (!ptr)
        return;

    s->malloc_count--;
    s->malloc_size -= qjs_malloc_usable_size(ptr) + MALLOC_OVERHEAD;
    fastFree(ptr);
}

static void* qjs_realloc(JSMallocState *s, void *ptr, size_t size)
{
    size_t old_size;

    if (!ptr) {
        if (size == 0)
            return NULL;
        return qjs_malloc(s, size);
    }

    old_size = qjs_malloc_usable_size(ptr);

    if (size == 0) {
        s->malloc_count--;
        s->malloc_size -= old_size + MALLOC_OVERHEAD;
        fastFree(ptr);
        return NULL;
    }

    if (s->malloc_size + size - old_size > s->malloc_limit)
        return NULL;

    ptr = fastRealloc(ptr, size);
    if (!ptr)
        return NULL;

    s->malloc_size += qjs_malloc_usable_size(ptr) - old_size;
    return ptr;
}

