现在我有了 QuickJS 官方的 **trace_malloc** 参考实现（`qjs.c` 中的 `-T` trace 模式）。这是 Bellard 自己写的自定义分配器示例。

## 关键发现

对比官方 `trace_mf` 实现和我们的实现：

### 官方 trace_malloc 的做法（Bellard 的参考写法）：

```c
static void *js_trace_malloc(JSMallocState *s, size_t size) {
    assert(size != 0);
    if (unlikely(s->malloc_size + size > s->malloc_limit))
        return NULL;
    ptr = malloc(size);
    if (ptr) {
        s->malloc_count++;
        s->malloc_size += js_trace_malloc_usable_size(ptr) + MALLOC_OVERHEAD;
    }
    return ptr;
}
```

**它确实加了 `MALLOC_OVERHEAD`！** 这不是可选的——它是 QuickJS 内存统计模型的一部分。

### 为什么需要 MALLOC_OVERHEAD？

QuickJS 的 GC 触发逻辑和内存限制检查都基于 `malloc_size`。如果我们不加 OVERHEAD：
- `malloc_size` 会比实际 RSS 偏小（因为每次 malloc 分配器都有 8-16 字节的内部元数据）
- `JS_SetMemoryLimit(rt, 10*1024*1024)` 设置 10MB 限制时，实际可能用到 12MB+ 才触发

### 我们的实现需要修正

当前实现**没有加 MALLOC_OVERHEAD**，这与官方参考写法不一致。让我修正：

input.newStr:
/*
 * Custom memory allocator for QuickJS using WTF::fastMalloc.
 *
 * This follows the same pattern as QuickJS's official trace_malloc
 * implementation in qjs.c (the -T flag). Key requirements:
 *
 * 1. js_malloc: assert(size != 0), check malloc_limit, update stats
 * 2. js_free: handle NULL, update stats
 * 3. js_realloc: ptr==NULL acts as malloc, size==0 acts as free
 * 4. js_malloc_usable_size: return platform usable size (or 0 if unavailable)
 * 5. MALLOC_OVERHEAD: accounts for allocator metadata per allocation
 *    (8 bytes on Linux/Windows, 0 on macOS which reports it in usable_size)
 */

#if defined(__APPLE__)
#define MALLOC_OVERHEAD  0
#else
#define MALLOC_OVERHEAD  8
#endif

static inline size_t qjs_malloc_usable_size(const void *ptr)
{
#if defined(__APPLE__)
    return malloc_size(ptr);
#elif defined(_WIN32)
    return _msize((void *)ptr);
#elif defined(HAVE_MALLOC_USABLE_SIZE)
    return malloc_usable_size(const_cast<void*>(ptr));
#else
    return 0;
#endif
}

static void* qjs_malloc(JSMallocState *s, size_t size)
{
    void *ptr;

    assert(size != 0);

    if (s->malloc_size + size > s->malloc_limit)
        return NULL;

    ptr = fastMalloc(size);
    if (ptr) {
        s->malloc_count++;
        s->malloc_size += qjs_malloc_usable_size(ptr) + MALLOC_OVERHEAD;
    }
    return ptr;
}

static void qjs_free(JSMallocState *s, void *ptr)
{
    if (!ptr)
        return;

    s->malloc_count--;
    s->malloc_size -= qjs_malloc_usable_size(ptr) + MALLOC_OVERHEAD;
    fastFree(ptr);
}

static void* qjs_realloc(JSMallocState *s, void *ptr, size_t size)
{
    size_t old_size;

    if (!ptr) {
        if (size == 0)
            return NULL;
        return qjs_malloc(s, size);
    }

    old_size = qjs_malloc_usable_size(ptr);

    if (size == 0) {
        s->malloc_count--;
        s->malloc_size -= old_size + MALLOC_OVERHEAD;
        fastFree(ptr);
        return NULL;
    }

    if (s->malloc_size + size - old_size > s->malloc_limit)
        return NULL;

    ptr = fastRealloc(ptr, size);
    if (ptr) {
        s->malloc_size += qjs_malloc_usable_size(ptr) - old_size;
    }
    return ptr;
}

