/*
 * Custom memory allocator for QuickJS using WTF::fastMalloc.
 *
 * QuickJS contract for JSMallocFunctions:
 * - js_malloc: must check malloc_limit, update malloc_count/malloc_size
 * - js_free: must update malloc_count/malloc_size
 * - js_realloc: must handle ptr==NULL (acts as malloc) and size==0 (acts as free)
 * - js_malloc_usable_size: returns usable size of ptr, or 0 if unknown
 *   (QuickJS falls back to js_malloc_usable_size_unknown returning 0 if NULL)
 *
 * When malloc_usable_size is available (Linux/macOS), we get precise tracking.
 * When unavailable, returning 0 disables string in-place concat optimization
 * but is otherwise safe — same as QuickJS on Emscripten.
 *
 * Note: QuickJS's default impl adds MALLOC_OVERHEAD(8) to approximate glibc
 * metadata cost. We don't do this because:
 * - With malloc_usable_size, tracking is already precise
 * - Without it, adding a constant doesn't improve accuracy
 */

static size_t qjs_malloc_usable_size(const void *ptr)
{
#ifdef HAVE_MALLOC_USABLE_SIZE
    return malloc_usable_size(const_cast<void*>(ptr));
#else
    return 0;
#endif
}

static void* qjs_malloc(JSMallocState *s, size_t size)
{
    void *ptr;

    assert(size != 0);

    if (s->malloc_size + size > s->malloc_limit)
