{
    size_t old_size;

    if (!ptr) {
        if (size == 0)
            return NULL;
        return qjs_malloc(s, size);
    }

    old_size = qjs_malloc_usable_size(ptr);

    if (size == 0) {
        s->malloc_count--;
        s->malloc_size -= old_size;
        fastFree(ptr);
        return NULL;
    }

    if (s->malloc_size + size - old_size > s->malloc_limit)
        return NULL;

    ptr = fastRealloc(ptr, size);
    if (!ptr)
        return NULL;

    s->malloc_size += qjs_malloc_usable_size(ptr) - old_size;
    return ptr;
}

